SELECT i.account_id AS "accountId", SUM(i.amount) AS "amount"
FROM fin_expense_claim_item i
JOIN fin_expense_claim c ON c.id = i.claim_id
WHERE c.status IN ('APPROVING', 'APPROVED') AND c.claim_date >= #{begin} AND c.claim_date <= #{end}
  AND c.dept_id = #{deptId}
  AND c.id <> #{excludeId}
GROUP BY i.account_id
